import { useState } from 'react';
import { JxAlert, JxButton, JxDivider, JxInputField, JxStepper, JxTable } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type SignupErrors = Partial<Record<keyof SignupValues, string>>;

interface SignupWizardProps {
  onSubmit: (values: SignupValues) => void | Promise<void>;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY: SignupValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

function validateStep(step: number, values: SignupValues): SignupErrors {
  const errors: SignupErrors = {};
  if (step === 0) {
    if (values.name.trim().length < 2) errors.name = 'Укажите имя целиком, минимум 2 символа';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) errors.email = 'Укажите адрес вида name@example.com';
    if (values.phone.replace(/\D/g, '').length < 10) errors.phone = 'Укажите номер из 10 цифр';
  }
  if (step === 1) {
    if (values.country.trim().length === 0) errors.country = 'Укажите страну';
    if (values.city.trim().length === 0) errors.city = 'Укажите город';
    if (values.street.trim().length === 0) errors.street = 'Укажите улицу и дом';
    if (!/^\d{5,6}$/.test(values.zip.trim())) errors.zip = 'Индекс — 5 или 6 цифр';
  }
  return errors;
}

export default function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(EMPTY);
  const [showErrors, setShowErrors] = useState(false);
  const [sending, setSending] = useState(false);
  const [sendError, setSendError] = useState<string | undefined>(undefined);

  const errors = validateStep(step, values);
  const visible = (field: keyof SignupValues) => (showErrors ? errors[field] : undefined);
  const isLast = step === STEPS.length - 1;

  const setField = (field: keyof SignupValues) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const next = event.target.value;
    setValues((current) => ({ ...current, [field]: next }));
  };

  const goBack = () => {
    setShowErrors(false);
    setSendError(undefined);
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (sending) return;

    if (Object.keys(errors).length > 0) {
      setShowErrors(true);
      return;
    }

    if (!isLast) {
      setShowErrors(false);
      setStep((current) => current + 1);
      return;
    }

    setSending(true);
    setSendError(undefined);
    try {
      await onSubmit(values);
    } catch {
      setSendError('Не удалось отправить данные. Проверьте соединение и попробуйте ещё раз.');
    } finally {
      setSending(false);
    }
  };

  const review: Array<{ label: string; value: string }> = [
    { label: 'Имя', value: values.name },
    { label: 'Почта', value: values.email },
    { label: 'Телефон', value: values.phone },
    { label: 'Страна', value: values.country },
    { label: 'Город', value: values.city },
    { label: 'Улица и дом', value: values.street },
    { label: 'Индекс', value: values.zip },
  ];

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 20,
        maxWidth: 520,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={STEPS} current={step} />

      <JxDivider />

      {showErrors && Object.keys(errors).length > 0 ? (
        <div role="alert">
          <JxAlert intent="danger" title="Проверьте поля шага">
            Часть полей заполнена не до конца — исправьте подсвеченные поля и повторите.
          </JxAlert>
        </div>
      ) : null}

      {sendError ? (
        <div role="alert">
          <JxAlert intent="danger" title="Отправка не удалась">
            {sendError}
          </JxAlert>
        </div>
      ) : null}

      {step === 0 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Имя и фамилия"
            name="name"
            autoComplete="name"
            required
            value={values.name}
            onChange={setField('name')}
            errorText={visible('name')}
          />
          <JxInputField
            label="Электронная почта"
            name="email"
            type="email"
            autoComplete="email"
            required
            value={values.email}
            onChange={setField('email')}
            helperText="Нужна для подтверждения регистрации"
            errorText={visible('email')}
          />
          <JxInputField
            label="Телефон"
            name="phone"
            type="tel"
            autoComplete="tel"
            prefix="+7"
            required
            value={values.phone}
            onChange={setField('phone')}
            errorText={visible('phone')}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxInputField
            label="Страна"
            name="country"
            autoComplete="country-name"
            required
            value={values.country}
            onChange={setField('country')}
            errorText={visible('country')}
          />
          <JxInputField
            label="Город"
            name="city"
            autoComplete="address-level2"
            required
            value={values.city}
            onChange={setField('city')}
            errorText={visible('city')}
          />
          <JxInputField
            label="Улица и дом"
            name="street"
            autoComplete="street-address"
            required
            value={values.street}
            onChange={setField('street')}
            errorText={visible('street')}
          />
          <JxInputField
            label="Почтовый индекс"
            name="zip"
            inputMode="numeric"
            autoComplete="postal-code"
            required
            value={values.zip}
            onChange={setField('zip')}
            errorText={visible('zip')}
          />
        </div>
      ) : null}

      {isLast ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          <JxAlert intent="info" title="Проверьте данные перед отправкой">
            Вернуться и поправить можно кнопкой «Назад».
          </JxAlert>
          <JxTable>
            <tbody>
              {review.map((row) => (
                <tr key={row.label}>
                  <th scope="row" style={{ whiteSpace: 'nowrap', color: 'var(--jx-text-2)' }}>
                    {row.label}
                  </th>
                  <td style={{ wordBreak: 'break-word' }}>{row.value}</td>
                </tr>
              ))}
            </tbody>
          </JxTable>
        </div>
      ) : null}

      <JxDivider />

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap' }}>
        <JxButton type="button" variant="ghost" onClick={goBack} disabled={step === 0 || sending}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={sending}>
          {isLast ? (sending ? 'Отправляем…' : 'Отправить') : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

